const taskEventRevisions = `-- name: TaskEventRevisions :many
SELECT e.task_id, e.event_key, e.source_revision, e.content_hash FROM normalize.task_event e
JOIN (
    SELECT ($1::uuid[])[i] AS task_id, ($2::text[])[i] AS event_key
    FROM generate_subscripts($1::uuid[], 1) AS i
) k ON e.task_id = k.task_id AND e.event_key = k.event_key
WHERE e.organization_id = $3
`

type TaskEventRevisionsParams struct {
	TaskIds        []uuid.UUID
	EventKeys      []string
	OrganizationID uuid.UUID
}

type TaskEventRevisionsRow struct {
	TaskID         uuid.UUID
	EventKey       string
	SourceRevision string
	ContentHash    []byte
}

func (q *Queries) TaskEventRevisions(ctx context.Context, arg TaskEventRevisionsParams) ([]TaskEventRevisionsRow, error) {
	rows, err := q.db.Query(ctx, taskEventRevisions, arg.TaskIds, arg.EventKeys, arg.OrganizationID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TaskEventRevisionsRow
	for rows.Next() {
		var i TaskEventRevisionsRow
		if err := rows.Scan(
			&i.TaskID,
			&i.EventKey,
			&i.SourceRevision,
			&i.ContentHash,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

